import 'dart:math' as math;
import 'package:b_ball/paintball/paintball_constants.dart';
import 'package:b_ball/paintball/logic/match_state.dart';

/// Distinct tactical action generated by [PaintballBotBrain].
sealed class BotAction {
  const BotAction();
}

/// Command for the bot to slide left (-1) or right (+1).
final class BotSlideAction extends BotAction {
  final int direction; // -1 or +1
  const BotSlideAction(this.direction);

  @override
  String toString() => 'BotSlideAction($direction)';
}

/// Command for the bot to adopt a new stance.
final class BotStanceAction extends BotAction {
  final PaintballStance stance;
  const BotStanceAction(this.stance);

  @override
  String toString() => 'BotStanceAction($stance)';
}

/// Command for the bot to fire at specific normalized screen coordinates.
final class BotFireAction extends BotAction {
  final double aimX;
  final double aimY;
  const BotFireAction({required this.aimX, required this.aimY});

  @override
  String toString() => 'BotFireAction(aimX: $aimX, aimY: $aimY)';
}

/// Lightweight snapshot of an incoming projectile flying towards the bot.
class IncomingProjectile {
  /// The lane on the bot's screen where the projectile will land (0..4).
  final int targetLane;

  /// Vertical height coordinate of the incoming ball (0.0..1.0).
  final double heightY;

  /// Time remaining until impact in seconds.
  double flightTimeRemaining;

  IncomingProjectile({
    required this.targetLane,
    required this.heightY,
    required this.flightTimeRemaining,
  });
}

/// Pure Dart autonomous bot AI for solo Paintball duels.
///
/// Implements Paintball Plan §6e:
/// - Decision cadence: Every 1.2–2.5 s picks slide (30%), stance (40%), shoot (30%).
/// - Reactive ducking: Reacts to incoming lethal projectiles with 250–450 ms delay
///   and a configurable fail-to-duck probability (default 35%).
class PaintballBotBrain {
  final math.Random _random;

  // ─── Cadence Timers ───────────────────────────────────────────────────────
  double _decisionTimer = 0.0;
  double _decisionInterval = 1.8;

  // ─── Reactive Ducking State ───────────────────────────────────────────────
  bool _isReactingToIncoming = false;
  double _reactionTimer = 0.0;
  bool _willDuckSuccessfully = true;

  // ─── Tunable Difficulty Knobs ─────────────────────────────────────────────
  /// Minimum time between autonomous decisions (seconds).
  final double minDecisionInterval;

  /// Maximum time between autonomous decisions (seconds).
  final double maxDecisionInterval;

  /// Minimum reaction delay before reacting to an incoming shot (seconds).
  final double minReactionDelay;

  /// Maximum reaction delay before reacting to an incoming shot (seconds).
  final double maxReactionDelay;

  /// Chance (0.0–1.0) that the bot fails to duck in time when a shot is coming.
  /// (0.35 means 65% successful dodge rate).
  final double failToDuckChance;

  PaintballBotBrain({
    int? seed,
    this.minDecisionInterval = 1.2,
    this.maxDecisionInterval = 2.5,
    this.minReactionDelay = 0.25,
    this.maxReactionDelay = 0.45,
    this.failToDuckChance = 0.35,
  }) : _random = math.Random(seed) {
    _resetDecisionTimer();
  }

  void _resetDecisionTimer() {
    _decisionInterval = minDecisionInterval +
        _random.nextDouble() * (maxDecisionInterval - minDecisionInterval);
    _decisionTimer = 0.0;
  }

  /// Advances bot cognition by [dt] seconds and optionally emits a [BotAction].
  ///
  /// - [bot]: The bot's own current player state.
  /// - [opponent]: The human opponent's current player state.
  /// - [incomingProjectiles]: List of paintballs currently in flight.
  BotAction? tick({
    required double dt,
    required PaintballPlayerState bot,
    required PaintballPlayerState opponent,
    List<IncomingProjectile> incomingProjectiles = const [],
  }) {
    if (bot.isEliminated) return null;

    // ─── 1. Reactive Defensive Evasion ──────────────────────────────────────
    final evasiveAction = _handleIncomingThreats(dt, bot, incomingProjectiles);
    if (evasiveAction != null) {
      return evasiveAction;
    }

    // ─── 2. Autonomous Tactical Cadence ─────────────────────────────────────
    _decisionTimer += dt;
    if (_decisionTimer < _decisionInterval) {
      return null;
    }
    _resetDecisionTimer();

    return _makeTacticalDecision(bot, opponent);
  }

  /// Checks for incoming projectiles aimed at the bot's occupied lane.
  BotAction? _handleIncomingThreats(
    double dt,
    PaintballPlayerState bot,
    List<IncomingProjectile> incomingProjectiles,
  ) {
    // If bot is already ducked or sliding, reactive evasion is not needed/possible.
    if (bot.stance == PaintballStance.duck || bot.isSliding) {
      _isReactingToIncoming = false;
      return null;
    }

    // Look for lethal incoming shots in bot's lane
    bool threatPresent = false;
    for (final p in incomingProjectiles) {
      if (bot.toSnapshot().occupiesLane(p.targetLane)) {
        // Is height lethal to bot's current stance?
        if (PaintballK.isHeightExposed(bot.stance, p.heightY)) {
          threatPresent = true;
          break;
        }
      }
    }

    if (threatPresent && !_isReactingToIncoming) {
      // Start reaction delay
      _isReactingToIncoming = true;
      _reactionTimer = minReactionDelay +
          _random.nextDouble() * (maxReactionDelay - minReactionDelay);
      _willDuckSuccessfully = _random.nextDouble() > failToDuckChance;
    }

    if (_isReactingToIncoming) {
      _reactionTimer -= dt;
      if (_reactionTimer <= 0.0) {
        _isReactingToIncoming = false;
        if (_willDuckSuccessfully) {
          return const BotStanceAction(PaintballStance.duck);
        }
      }
    }

    return null;
  }

  /// Decides between Slide (30%), Change Stance (40%), and Shoot (30%).
  BotAction? _makeTacticalDecision(
    PaintballPlayerState bot,
    PaintballPlayerState opponent,
  ) {
    // If bot is ducked and out of ammo, stay ducked until reloaded!
    if (bot.stance == PaintballStance.duck && bot.ammo < 3) {
      return null;
    }

    // If out of ammo, prioritize ducking to reload
    if (bot.ammo == 0 && bot.stance != PaintballStance.duck) {
      return const BotStanceAction(PaintballStance.duck);
    }

    final roll = _random.nextDouble();

    // 30% Slide
    if (roll < 0.30) {
      return _chooseSlide(bot);
    }
    // 40% Stance Change (0.30 .. 0.70)
    else if (roll < 0.70) {
      return _chooseStance(bot);
    }
    // 30% Shoot (0.70 .. 1.00)
    else {
      return _chooseShot(bot, opponent);
    }
  }

  BotAction? _chooseSlide(PaintballPlayerState bot) {
    if (bot.isSliding) return null;

    final canGoLeft = bot.lane > PaintballK.minLane;
    final canGoRight = bot.lane < PaintballK.maxLane;

    if (!canGoLeft && !canGoRight) return null;

    int direction;
    if (canGoLeft && canGoRight) {
      direction = _random.nextBool() ? -1 : 1;
    } else {
      direction = canGoLeft ? -1 : 1;
    }

    return BotSlideAction(direction);
  }

  BotAction? _chooseStance(PaintballPlayerState bot) {
    if (bot.isSliding) return null;

    // Pick from the other two stances
    final options = PaintballStance.values
        .where((s) => s != bot.stance)
        .toList(growable: false);

    // If ammo is full, avoid ducking
    final filtered = (bot.ammo == PaintballK.maxAmmo)
        ? options.where((s) => s != PaintballStance.duck).toList()
        : options;

    if (filtered.isEmpty) return null;
    final nextStance = filtered[_random.nextInt(filtered.length)];
    return BotStanceAction(nextStance);
  }

  BotAction? _chooseShot(
    PaintballPlayerState bot,
    PaintballPlayerState opponent,
  ) {
    if (!bot.canFire) {
      // If ducked and ready, peek up to stand or crouch
      if (bot.stance == PaintballStance.duck && bot.ammo > 0) {
        return const BotStanceAction(PaintballStance.stand);
      }
      return null;
    }

    // Target the opponent's lane
    // On the bot's screen, opponent's lane L_opp mirrors to 4 - L_opp
    final targetLaneOnBotScreen = PaintballK.mirrorLane(opponent.lane);
    final baseAimX = PaintballK.laneToAimX(targetLaneOnBotScreen);

    // Small aim scatter (±0.06) to feel human
    final jitterX = (_random.nextDouble() - 0.5) * 0.12;
    final aimX = (baseAimX + jitterX).clamp(-1.0, 1.0);

    // Height: aim at head/torso (0.60..0.72)
    final aimY = 0.60 + _random.nextDouble() * 0.12;

    return BotFireAction(aimX: aimX, aimY: aimY);
  }
}
